import React, { useState } from "react";
import { AddCar } from "../../services/ApiCar";

export default function CardAddVoiture() {
  const [newCar, setNewCar] = useState({
    matricule: "",
    model: "",
    Libelle: "",
    prix: "",
    Prix_Jour: "",
    Couleur: "",
    voiture_image: null,
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewCar({ ...newCar, [name]: value });
  };

  const handleImageChange = (e) => {
    setNewCar({ ...newCar, voiture_image: e.target.files[0] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const formData = new FormData();
      for (let key in newCar) {
        formData.append(key, newCar[key]);
      }
      await AddCar(formData);
      alert("Car added successfully!");
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Add New Car</h6>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          {/* Car Information */}
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
            Car Information
          </h6>
          <div className="flex flex-wrap">
            {/* Repeat input blocks like this */}
            <InputField label="Matricule" name="matricule" value={newCar.matricule} onChange={handleChange} />
            <InputField label="Model" name="model" value={newCar.model} onChange={handleChange} />
            <InputField label="Libelle" name="Libelle" value={newCar.Libelle} onChange={handleChange} />
            <InputField label="Prix" name="prix" value={newCar.prix} onChange={handleChange} type="number" />
            <InputField label="Prix_Jour" name="Prix_Jour" value={newCar.Prix_Jour} onChange={handleChange} type="number" />
            <InputField label="Couleur" name="Couleur" value={newCar.Couleur} onChange={handleChange} />
          </div>

          {/* Image Upload */}
          <div className="w-full lg:w-6/12 px-4">
            <div className="relative w-full mb-3">
              <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2" htmlFor="voiture_image">
                Image
              </label>
              <input
                type="file"
                name="voiture_image"
                id="voiture_image"
                onChange={handleImageChange}
                className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full"
              />
            </div>
          </div>

          {/* Submit */}
          <div className="text-center mt-6">
            <button
              type="submit"
              className="bg-lightBlue-500 text-white active:bg-lightBlue-600 font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md"
            >
              Add Car
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

function InputField({ label, name, value, onChange, type = "text" }) {
  return (
    <div className="w-full lg:w-6/12 px-4">
      <div className="relative w-full mb-3">
        <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2" htmlFor={name}>
          {label}
        </label>
        <input
          type={type}
          name={name}
          id={name}
          value={value}
          onChange={onChange}
          className="border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full"
          placeholder={`Enter ${label.toLowerCase()}`}
        />
      </div>
    </div>
  );
}
